## Building a String Utilities Module

```xiom
mod strutils {
  pub fn reverse(s: Str) -> Str {
    let mut result = "";
    let mut i = s.len();
    while i > 0 {
      i -= 1;
      let ch = s.get(i).unwrap();
      result = string.str_concat(result, string.from_char(ch));
    };
    result
  }

  pub fn count_words(s: Str) -> Int {
    if s.len() == 0 { return 0; };
    let mut count = 0;
    let mut in_word = false;
    let mut i = 0;
    while i < s.len() {
      let ch = s.get(i).unwrap();
      if ch == ' ' {
        in_word = false;
      } else if !in_word {
        count += 1;
        in_word = true;
      };
      i += 1;
    };
    count
  }

  pub fn capitalize(s: Str) -> Str {
    if s.len() == 0 { return ""; };
    let first = s.get(0).unwrap();
    let rest = s.slice(1, s.len());
    string.str_concat(string.from_char(first), rest)
  }

  pub fn truncate(s: Str, max_len: Int) -> Str {
    if s.len() <= max_len { return s; };
    s.slice(0, max_len)
  }
}
```

### Patterns Used

- **reverse**: Build result backwards character by character
- **count_words**: Track whether you're inside a word (non-space sequence)
- **capitalize**: Take first char + rest of string
- **truncate**: Slice to max length if too long

