use xiom.io;

use xiom.string;
use xiom.convert.tostring;
module strutils {
  pub fn reverse(s: Str) -> Str {
    var result = "";
    var i = s.len();
    while i > 0 {
      i -= 1;
      let ch = s.char_at(i);
      result = string.str_concat(result, to_string_char(ch));
    };
    result
  }

  pub fn count_words(s: Str) -> Int {
    if s.len() == 0 { return 0; };
    var count = 0;
    var in_word = false;
    var i = 0;
    while i < s.len() {
      let ch = s.char_at(i);
      if ch == ' ' {
        in_word = false;
      } else if !in_word {
        count += 1;
        in_word = true;
      };
      i += 1;
    };
    count
  }

  pub fn truncate(s: Str, max_len: Int) -> Str {
    if s.len() <= max_len { return s; };
    s.slice(0, max_len)
  }
}

fn main() -> Int {
  let rev = strutils.reverse("hello");
  io.println(rev.to_str());
  let words = strutils.count_words("hello world again");
  io.println(words.to_str());
  let trun = strutils.truncate("abcdefghij", 5);
  io.println(trun.to_str());
  return 0;
}
